                  '**Kafka 的架构可以只用五个名词讲完**：**Broker、Topic、Partition、Replica、ISR**。**先说最容易混的一层**：**Topic 是「逻辑上的消息类别」，Partition 是「物理上的存储单元」**——**一个 Topic 拆成 N 个 Partition，每个 Partition 在磁盘上就是「一个目录 + 一组 segment 文件」**，**目录名是 `topic-partition`（如 `orders-3`）**。**所以「Topic 只是元数据，真正存数据的是 Partition」**。',
                  '**Replica 是「Partition 的副本」**——**每个 Partition 有 1 个 leader 和 N-1 个 follower**，**生产者和消费者只跟 leader 打交道**（**3.0 之前读也走 leader**；**2.4 起有 follower 读的雏形，但不推荐**），**follower 的唯一职责是「不停地向 leader 发 fetch 请求，把数据拉过来」**。**注意这个方向**：**是 follower「拉」，不是 leader「推」**——**这是 Kafka 减少「推模式流控复杂度」的关键设计**，**也让「follower 挂一会儿再回来」能自动追上（按 offset 续拉）**。',
