                  '**为什么不用 ZooKeeper？这是必考题，答案有三层**。**第一层（架构）**：**ZK 是「CP 系统」，选主期间（几十秒）整个注册中心不可用**；**NameServer 是「AP 的近似实现」——节点各自独立、不选举，只要有一个活着就能服务**，**对「路由中心」这种「读多写少、允许短暂不一致」的场景更合适**。**第二层（运维）**：**RocketMQ 要「自建一套 ZK 集群」的运维成本**，**而 NameServer 是「一个极简的 Java 进程」，几千行代码，起起来就能用**。**第三层（一致性需求）**：**路由信息「短暂不一致」是可接受的**——**Producer 拿到「稍旧的路由」最多是「发到一台已经不做 leader 的 Broker」，客户端会收到「重试 + 重新拉路由」，自愈**。**所以「不需要强一致的场景，不要用强一致的组件」**——**这句话是这道题的最高分回答**。',
                  '**Broker 侧有两个细节值得说**：**① 主从（Master/Slave）在 4.x 是「指定 master/slave 角色 + 同步/异步复制」，5.0 引入「DLedger Controller 模式」支持自动选主**（**4.x 的 master 挂了需要人工或脚本切换，这是它相对 Kafka 的一个短板**）；**② 「Broker 与 Topic 的关系」是「一个 Topic 的队列分散在多个 Broker 上」**——**默认 `brokerRole=ASYNC_MASTER`、`flushDiskType=ASYNC_FLUSH`**，**可靠性靠「主从同步」而不是「同步刷盘」**（**与 Kafka 的思路一致：用冗余换吞吐**）。',
