                  '**C（Consistency）= 线性一致性（linearizability）**，**不是「所有节点数据一样」，也不是「最终一致」**。**它的严格定义是**：**「存在一个全局时钟顺序，使得「每个读操作都返回「它之前最近一次写」的值」，且「所有客户端看到的顺序一致」」**。**通俗说就是「一旦写入成功，之后任何节点的读都必须读到这个值」**——**这是一条「单对象、实时」的强约束**。**所以「主从异步复制 + 读到旧数据」在 CAP 里就是「放弃 C」**（**哪怕它「1 秒后一致」**）。',
