                  '**先说清「本地事务为什么能工作」**：**数据库的 ACID 依赖三个前提**——**① 「所有操作在同一个数据库连接、同一个存储引擎里」**；**② 「有一个「提交点」（`COMMIT` 那一刻），在此之前可以全部回滚」**；**③ 「有锁与 MVCC 保证隔离」**。**分布式场景把这三个前提全打破了**：**数据分在不同库/不同服务（连接不同）**、**没有「跨库的统一提交点」**、**跨服务的锁根本不存在**。**所以「分布式事务」的本质问题是**：**「多个独立的本地事务，如何「要么都成功要么都不生效」，且中间状态不被外人看到」**。',
                  '**三种典型触发场景（面试可以先分类）**：**① 分库分表后的跨库操作**（**同一业务表被拆到两个库，「扣 A 库余额、加 B 库余额」**）；**② 微服务拆分后的跨服务操作**（**订单服务 + 库存服务 + 账户服务，各自独立库**）；**③ 跨异构系统**（**数据库 + 缓存 + 消息 + 第三方接口**，**如「下单成功要发短信、写 ES、扣积分」**）。**注意第 ③ 类最容易被忽略**：**它不属于「数据库事务」范畴，任何 2PC 协议都管不到第三方接口**。',
