                solution:
                  'public class Snowflake {\n' +
                  '    private static final long EPOCH = 1577836800000L;\n' +
                  '    private static final long WORKER_BITS = 5L, DATACENTER_BITS = 5L, SEQUENCE_BITS = 12L;\n' +
                  '    private static final long MAX_WORKER = ~(-1L << WORKER_BITS);\n' +
                  '    private static final long MAX_DATACENTER = ~(-1L << DATACENTER_BITS);\n' +
                  '    private static final long SEQUENCE_MASK = ~(-1L << SEQUENCE_BITS);\n' +
                  '    private static final long WORKER_SHIFT = SEQUENCE_BITS;\n' +
                  '    private static final long DATACENTER_SHIFT = SEQUENCE_BITS + WORKER_BITS;\n' +
                  '    private static final long TIMESTAMP_SHIFT = SEQUENCE_BITS + WORKER_BITS + DATACENTER_BITS;\n' +
                  '\n' +
                  '    private final long workerId, datacenterId;\n' +
                  '    private long sequence = 0L;\n' +
                  '    private long lastTimestamp = -1L;\n' +
                  '\n' +
                  '    public Snowflake(long workerId, long datacenterId) {\n' +
                  '        if (workerId < 0 || workerId > MAX_WORKER) throw new IllegalArgumentException("workerId");\n' +
                  '        if (datacenterId < 0 || datacenterId > MAX_DATACENTER) throw new IllegalArgumentException("datacenterId");\n' +
                  '        this.workerId = workerId;\n' +
                  '        this.datacenterId = datacenterId;\n' +
                  '    }\n' +
                  '\n' +
                  '    public synchronized long nextId() {\n' +
                  '        long now = System.currentTimeMillis();\n' +
                  '        if (now < lastTimestamp) {\n' +
                  '            long offset = lastTimestamp - now;\n' +
                  '            if (offset > 5L) throw new IllegalStateException("clock moved backwards " + offset + "ms");\n' +
                  '            try { wait(offset << 1); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n' +
                  '            now = System.currentTimeMillis();\n' +
                  '            if (now < lastTimestamp) throw new IllegalStateException("clock moved backwards");\n' +
                  '        }\n' +
                  '\n' +
                  '        if (now == lastTimestamp) {\n' +
                  '            sequence = (sequence + 1) & SEQUENCE_MASK;\n' +
                  '            if (sequence == 0) now = tilNextMillis(lastTimestamp);\n' +
                  '        } else {\n' +
                  '            sequence = 0L;\n' +
                  '        }\n' +
                  '\n' +
                  '        lastTimestamp = now;\n' +
                  '        return ((now - EPOCH) << TIMESTAMP_SHIFT)\n' +
                  '                | (datacenterId << DATACENTER_SHIFT)\n' +
                  '                | (workerId << WORKER_SHIFT)\n' +
                  '                | sequence;\n' +
                  '    }\n' +
                  '\n' +
                  '    private long tilNextMillis(long last) {\n' +
                  '        long ts = System.currentTimeMillis();\n' +
                  '        while (ts <= last) ts = System.currentTimeMillis();\n' +
                  '        return ts;\n' +
                  '    }\n' +
                  '}',
