                  '**按六层讲职责**：**接入（TLS 卸载、连接复用）→ 安全（鉴权、黑白名单、防重放、WAF）→ 流量（全局限流、熔断、灰度染色、A/B）→ 路由（Path/Host/Header/权重）→ 转换（协议转换、报文改写、BFF 聚合）→ 观测（access log、指标、traceId 生成与透传）**。',
