              '「进程是资源分配单位、线程是调度单位」这句话人人会背，**但它背后是一整套「谁拥有什么、切一次要付多少代价」的账**。**这一课的主线只有一条**：**「隔离性越强，切换越贵」**——**进程隔离得最彻底（独立地址空间 + 独立页表），所以切换要换页表、刷 TLB、废缓存**；**线程共享地址空间，只需换寄存器与栈**；**协程连栈都自己管，切换就是「改一个指针」**。**把这条「隔离 ↔ 开销」的轴握住，Q54、Q57、Q59 全部从它推出来**；**剩下的 IPC、COW、僵尸进程，则是「隔离带来的沟通成本」与「生命周期管理」两个衍生话题**。',
