                  '**「线程到底拥有什么」是最容易被追问的点**：**线程私有的是「栈（默认 1MB）、寄存器上下文、程序计数器、TCB、线程局部存储（TLS）、`errno`、信号掩码、调度优先级」**；**共享的是「代码段、数据段（全局/静态变量）、堆、打开的文件描述符、当前工作目录、信号处理函数」**。**由此可以推出两个经典结论**：**① 「局部变量线程安全、全局变量不安全」**（**前者在各自栈上，后者在共享数据段/堆**）；**② 「一个线程 `close(fd)`，其他线程也读不了了」**（**fd 表是共享的**）——**这两个推论比背清单更能证明你理解了。**',
                  '**协程的关键是「栈的处理方式」**：**线程的栈由内核管理（用户栈 + 内核栈），切换必须进内核**；**协程的栈由运行时（用户态）管理**，**分「有栈协程」（Go 的 goroutine、Java 的 Loom 虚拟线程，各自有独立栈，可 2KB 起步并动态伸缩）与「无栈协程」（`async/await`、Kotlin 的 suspend，靠编译器把状态塞进一个状态机对象，没有独立栈）**。**所以协程切换 = 「保存几个寄存器 + 换个栈指针」，通常 20~100ns**，**而线程切换 1~10μs，进程切换 3~20μs**。**差一到两个数量级。**',
