                title: 'Q72 · 用户态与内核态的区别，什么情况下切换',
                questionId: 'java-09-Q72',
                intent:
                  '**考官想确认「你知道这道墙是硬件强制的」，以及「切换的成本观」。**',
                points: [
                  '**区别**：**内核态（ring 0）可执行特权指令**（**改页表、开关中断、读写 IO 端口、访问任意物理地址**）；**用户态（ring 3）只能执行非特权指令、只能访问自己的映射区**。**这道墙由 CPU 硬件强制（越权指令直接 `#GP`）**。',
                  '**三种切换入口**：**系统调用（主动：`read`/`write`/`open`/`fork`/`mmap`）**、**中断（被动异步：网卡收包、磁盘完成、时钟中断、软中断）**、**异常（被动同步：缺页、除零、非法指令、断点）**。',
                  '**开销**：**保存/恢复上下文 + 切内核栈 + 内核逻辑执行 + 可能污染 cache/TLB（`KPTI` 后每次系统调用还要换页表）**——**纯切换 ~100~300ns，但一次 `read` 的端到端可能几微秒。**',
                  '**为什么要这道墙**：**防止应用破坏系统（越权改页表、关中断、直接操作硬件）**，**同时保证「一个进程崩溃不影响别人」**。',
                  '**补一句「所以优化方向是减少跨边界」**：**批量 IO（`readv`/`writev`）、内存映射（`mmap`）、零拷贝（`sendfile`）、用户态网络栈（DPDK）**——**本质都是「把 N 次过门压成 1 次」。**',
                ],
                depth:
                  '**能补「`CAS` 不需要进内核」**：**`CAS` 是 CPU 指令（`lock cmpxchg`），纯用户态完成，只锁缓存行**——**所以「无锁编程」是真无锁（不进内核）**。**而 `synchronized` 在「有竞争」时会走 `futex` 系统调用挂起线程**（**无竞争时靠偏向锁/轻量级锁在用户态解决**）——**这条区分能把「锁膨胀」的过程说出来。**',
                followup:
                  '**「中断上下文为什么不能睡眠？」**——**它没有「可被调度的任务结构」，一旦睡眠内核无法恢复执行**，**所以驱动要拆「上半部（快、不睡眠）+ 下半部（`softirq`/`tasklet`/`workqueue`，可延后）」。** **「系统调用能被中断吗？」**——**能，被信号中断时会返回 `-EINTR`**，**所以「`read` 返回 `-1` 且 `errno == EINTR`」要重试**（**Java 里 `InterruptedException` 就是这类语义的封装**）。',
